describe('Deep Links Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should load correct page when navigating via deep link', () => {
    cy.visit('/products/electronics');
    cy.get('[data-testid="page-title"]').should('contain', 'Electronics Products');
    cy.get('[data-testid="product-list"]').should('be.visible');
    cy.get('[data-testid="product-card"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="breadcrumb"]').should('contain', 'Home > Products > Electronics');
  });

  it('should handle invalid deep link gracefully', () => {
    cy.visit('/products/invalid-category');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Page not found');
    cy.get('[data-testid="home-button"]').should('be.visible');
    cy.get('[data-testid="home-button"]').click();
    cy.url().should('eq', Cypress.config().baseUrl + '/');
  });
});
